Here is the commit message:
drm/msm/dpu: fix error check return value of
 irq_of_parse_and_map()

The irq_of_parse_and_map() function returns 0 on failure, and does not
return a negative value anyhow, so never enter this conditional branch.

Fixes: 25fdd5933e4c ("drm/msm: Add SDM845 DPU support")
Reported-by: Zeal Robot <zealci@zte.com.cn>
Signed-off-by: Lv Ruyi <lv.ruyi@zte.com.cn>
Reviewed-by: Stephen Boyd <swboyd@chromium.org>
Patchwork: https://patchwork.freedesktop.org/patch/483291/
Link: https://lore.kernel.org/r/20220425090947.3498897-1-lv.ruyi@zte.com.cn
Signed-off-by: Dmitry Baryshkov <dmitry.baryshkov@linaro.org>

Here is the root cause:
The bug was caused by an incorrect assumption in the error handling logic for the `irq_of_parse_and_map()` function, which was believed to return a negative value on failure. In reality, this function returns 0 on failure, leading to the conditional branch being incorrectly entered, which could result in misleading error messages and improper handling of the IRQ initialization process.

Here is the patch:

 static int dpu_kms_init(struct drm_device *ddev)
 {
 	struct msm_drm_private *priv = ddev->dev_private;
 	struct device *dev = ddev->dev;
 	struct platform_device *pdev = to_platform_device(dev);
 	struct dpu_kms *dpu_kms;
 	int irq;
 	int ret = 0;

 	dpu_kms = devm_kzalloc(&pdev->dev, sizeof(*dpu_kms), GFP_KERNEL);
 	if (!dpu_kms)
 		return -ENOMEM;

 	ret = devm_pm_opp_set_clkname(dev, "core");
 	if (ret)
 		return ret;
 	/* OPP table is optional */
 	ret = devm_pm_opp_of_add_table(dev);
 	if (ret && ret != -ENODEV) {
 		dev_err(dev, "invalid OPP table in device tree\n");
 		return ret;
 	}

 	ret = devm_clk_bulk_get_all(&pdev->dev, &dpu_kms->clocks);
 	if (ret < 0) {
 		DPU_ERROR("failed to parse clocks, ret=%d\n", ret);
 		return ret;
 	}
 	dpu_kms->num_clocks = ret;

 	ret = msm_kms_init(&dpu_kms->base, &kms_funcs);
 	if (ret) {
 		DPU_ERROR("failed to init kms, ret=%d\n", ret);
 		return ret;
 	}
 	dpu_kms->dev = ddev;
 	dpu_kms->pdev = pdev;

 	pm_runtime_enable(&pdev->dev);
 	dpu_kms->rpm_enabled = true;

 	priv->kms = &dpu_kms->base;

 	irq = irq_of_parse_and_map(dpu_kms->pdev->dev.of_node, 0);
-	if (irq < 0) {
-		DPU_ERROR("failed to get irq: %d\n", irq);
-		return irq;
+	if (!irq) {
+		DPU_ERROR("failed to get irq\n");
+		return -EINVAL;
 	}
 	dpu_kms->base.irq = irq;

 	return 0;
 }



